function loose_parse(text) {
  if (!text) return null;

  // 1. Initial cleanup: Remove Markdown code blocks and whitespace
  let currentText = text.replace(/```json/gi, '').replace(/```/g, '').trim();

  // 2. Fast Path: Try parsing immediately (in case cleanup was enough)
  try {
    return JSON.parse(currentText);
  } catch (e) {
    // Continue to advanced repair strategies
  }

  // 3. Extraction: Isolate the JSON object/array from surrounding text
  // (e.g., "Here is the data: { ... } Hope this helps!")
  const firstCurly = currentText.indexOf('{');
  const firstSquare = currentText.indexOf('[');

  let startIdx = -1;
  let endIdx = -1;

  // Determine if we are looking for an Object {} or Array []
  if (firstCurly !== -1 && (firstSquare === -1 || firstCurly < firstSquare)) {
    startIdx = firstCurly;
  } else if (firstSquare !== -1) {
    startIdx = firstSquare;
  }

  if (startIdx !== -1) {
    // Find the last matching closing bracket to strip trailing text
    // Note: This is a simple look-ahead; for nested structures, we rely on the parser later.
    const lastCurly = currentText.lastIndexOf('}');
    const lastSquare = currentText.lastIndexOf(']');
    endIdx = Math.max(lastCurly, lastSquare);

    if (endIdx > startIdx) {
      currentText = currentText.substring(startIdx, endIdx + 1);
    } else {
      // If no closing bracket found, assume truncated and take everything
      currentText = currentText.substring(startIdx);
    }
  }

  // 4. Syntax Repair: Fix common JSON invalidities
  // Fix 1: Remove trailing commas (e.g., {"a": 1,} -> {"a": 1})
  currentText = currentText.replace(/,(\s*[}\]])/g, '$1');

  // Try parsing again after extraction and minor repairs
  try {
    return JSON.parse(currentText);
  } catch (e) {
    // Continue to truncation handling
  }

  // 5. Truncation Repair: Balance unclosed braces/brackets/quotes
  // This handles cases where the token limit cut off the response
  let stack = [];
  let inString = false;
  let isEscaped = false;

  // We rebuild the string char by char to track state
  for (let i = 0; i < currentText.length; i++) {
    const char = currentText[i];

    if (isEscaped) {
      isEscaped = false;
      continue;
    }

    if (char === '\\') {
      isEscaped = true;
      continue;
    }

    if (char === '"') {
      inString = !inString;
    }

    if (!inString) {
      if (char === '{') stack.push('}');
      else if (char === '[') stack.push(']');
      else if (char === '}' || char === ']') {
        // If we find a closing bracket that matches the stack, pop it
        if (stack.length > 0 && stack[stack.length - 1] === char) {
          stack.pop();
        }
      }
    }
  }

  // Close any open string
  if (inString) currentText += '"';

  // Close any open structures (reverse order)
  while (stack.length > 0) {
    currentText += stack.pop();
  }

  try {
    return JSON.parse(currentText);
  } catch (e) {}

  // 6. Last Resort: "JavaScipt Object" Fallback
  // Useful if the LLM used single quotes {'key': 'val'} or unquoted keys {key: "val"}
  // We use `new Function` (safer than eval, but still requires trust in the input source)
  try {
    const fn = new Function(`return ${currentText}`);
    return fn();
  } catch (e) {
    console.error("loose_parse failed to recover JSON info", e);
    return null; // Return null if absolutely unrecoverable
  }
}
