/**
 * Flexible Financial Reconciliation (Handles Sign Flips & Variable Balance Locations)
 * 
 * Key Features:
 * - Computes total balance from transactions (running balance)
 * - Handles initial balance from multiple possible locations
 * - Reconciles even when AI flips signs (matches on absolute values)
 * - Provides comprehensive reconciliation statistics
 * 
 * Input: Array of items where each item.json = { "response": {..., "summary": {...}, "transactions": [...]} }
 * Output: Each item augmented with 'compute' object containing reconciliation results
 */

let item = $input.item;
const TOLERANCE = 0.001;

// --- 1. VALIDATE INPUT ---
if (!item || typeof item !== 'object') {
    return item;
}

item.json = item.json || {};
const compute = {};
const docContent = item.json.response;

if (!docContent || typeof docContent !== 'object') {
    compute.reconciliation_result = false;
    compute.error_details = "FATAL ERROR: Missing or invalid 'response' object.";
    item.json = { docContent, compute };
    return item;
}

const summary = docContent.summary;
const transactions = docContent.transactions || [];

if (!summary) {
    compute.reconciliation_result = false;
    compute.error_details = "FATAL ERROR: Missing 'summary' object in response.";
    item.json = { docContent, compute };
    return item;
}

// --- 2. COMPUTE TOTALS FROM TRANSACTIONS ---
let computedTotalDebit = 0;
let computedTotalCredit = 0;
let computedTotalBalance = 0;

for (const transaction of transactions) {
    const debit = parseFloat(transaction.debit_amount) || 0;
    const credit = parseFloat(transaction.credit_amount) || 0;

    computedTotalDebit += debit;
    computedTotalCredit += credit;
    computedTotalBalance += (debit - credit); // Net change per transaction
}

// --- 3. EXTRACT SUMMARY VALUES (with flexible initial balance detection) ---
const summaryTotalDebit = parseFloat(summary.total_debit_amount) || 0;
const summaryTotalCredit = parseFloat(summary.total_credit_amount) || 0;
const finalBalance = parseFloat(summary.final_accumulated_balance) || 0;

// Try multiple possible initial balance locations
const initialDocBalance = parseFloat(summary.initial_document_balance) || parseFloat(summary.initial_balance) || 0;
const cutoffBalance = parseFloat(summary.cutoff_accumulated_balance) || 0;

// Determine which initial balance to use (prefer non-zero values)
const possibleInitials = [initialDocBalance, cutoffBalance, initialDocBalance + cutoffBalance];
const initialBalance = possibleInitials.find(val => Math.abs(val) > TOLERANCE) || 0;

// --- 4. FLEXIBLE RECONCILIATION (handles sign flips) ---

// Helper function to check if two values match (considering sign flips)
const isMatch = (val1, val2, tolerance = TOLERANCE) => {
    return Math.abs(val1 - val2) <= tolerance || Math.abs(Math.abs(val1) - Math.abs(val2)) <= tolerance;
};

// Debit Reconciliation (check both normal and flipped signs, but only if summary value exists)
const debitDiff = computedTotalDebit - summaryTotalDebit;
const hasDebitSummary = Math.abs(summaryTotalDebit) > TOLERANCE;
const isDebitReconciled = !hasDebitSummary || isMatch(computedTotalDebit, summaryTotalDebit);

// Credit Reconciliation (only if summary value exists)
const creditDiff = computedTotalCredit - summaryTotalCredit;
const hasCreditSummary = Math.abs(summaryTotalCredit) > TOLERANCE;
const isCreditReconciled = !hasCreditSummary || isMatch(computedTotalCredit, summaryTotalCredit);

// --- 5. BALANCE RECONCILIATION (test all combinations) ---

// Calculate expected final balances using different initial balance sources
const expectedBalances = [
    initialBalance + summaryTotalDebit - summaryTotalCredit,
    initialDocBalance + summaryTotalDebit - summaryTotalCredit,
    cutoffBalance + summaryTotalDebit - summaryTotalCredit,
    initialBalance + computedTotalBalance // Using computed net change
];

// Check if ANY expected balance matches the final balance (with sign flexibility)
const balanceChecks = expectedBalances.map(expected => ({
    expected,
    difference: expected - finalBalance,
    matches: isMatch(expected, finalBalance)
}));

const isBalanceReconciled = balanceChecks.some(check => check.matches);
const bestBalanceMatch = balanceChecks.find(check => check.matches) || balanceChecks[0];

// --- 6. POPULATE COMPUTE OBJECT ---

// Source Data
compute.initial_balance = initialBalance;
compute.initial_document_balance = initialDocBalance;
compute.cutoff_accumulated_balance = cutoffBalance;
compute.actual_final_balance = finalBalance;

// Computed Transaction Totals
compute.computed_total_debit = computedTotalDebit;
compute.computed_total_credit = computedTotalCredit;
compute.computed_net_change = computedTotalBalance;

// Summary Totals
compute.summary_total_debit = summaryTotalDebit;
compute.summary_total_credit = summaryTotalCredit;

// Debit Reconciliation
compute.debit_reconciliation_result = isDebitReconciled;
compute.debit_difference = debitDiff;
compute.debit_abs_difference = Math.abs(debitDiff);
compute.debit_summary_available = hasDebitSummary;

// Credit Reconciliation
compute.credit_reconciliation_result = isCreditReconciled;
compute.credit_difference = creditDiff;
compute.credit_abs_difference = Math.abs(creditDiff);
compute.credit_summary_available = hasCreditSummary;

// Balance Reconciliation
compute.balance_reconciliation_result = isBalanceReconciled;
compute.expected_final_balance = bestBalanceMatch.expected;
compute.balance_difference = bestBalanceMatch.difference;
compute.balance_abs_difference = Math.abs(bestBalanceMatch.difference);

// All tested balance scenarios
compute.all_balance_scenarios = expectedBalances.map((exp, idx) => ({
    scenario: idx,
    expected: exp,
    difference: exp - finalBalance,
    reconciled: balanceChecks[idx].matches
}));

// Overall Result
compute.reconciliation_result = isBalanceReconciled && isDebitReconciled && isCreditReconciled;
compute.tolerance = TOLERANCE;

// Detailed Status Message
if (!compute.reconciliation_result) {
    let errors = [];
    if (!isBalanceReconciled) errors.push(`Balance mismatch (Δ: ${bestBalanceMatch.difference.toFixed(3)})`);
    if (!isDebitReconciled && hasDebitSummary) errors.push(`Debit mismatch (Δ: ${debitDiff.toFixed(3)})`);
    if (!isCreditReconciled && hasCreditSummary) errors.push(`Credit mismatch (Δ: ${creditDiff.toFixed(3)})`);

    compute.error_details = errors.length > 0 ? `Reconciliation Failed: ${errors.join('; ')}` : 'Reconciliation PASSED (summary totals not provided, balance verified)';
    compute.reconciliation_summary = {
        status: errors.length > 0 ? 'FAILED' : 'PASSED',
        passed_checks: [isBalanceReconciled, isDebitReconciled, isCreditReconciled].filter(Boolean).length,
        total_checks: 3,
        skipped_checks: [
            !hasDebitSummary ? 'debit' : null,
            !hasCreditSummary ? 'credit' : null
        ].filter(Boolean)
    };
} else {
    const skippedChecks = [
        !hasDebitSummary ? 'debit' : null,
        !hasCreditSummary ? 'credit' : null
    ].filter(Boolean);

    compute.error_details = skippedChecks.length > 0 
        ? `Reconciliation PASSED (${skippedChecks.join(', ')} totals not provided, balance verified)` 
        : `Reconciliation PASSED (tolerance: ${TOLERANCE})`;
    compute.reconciliation_summary = {
        status: 'PASSED',
        passed_checks: 3,
        total_checks: 3,
        skipped_checks: skippedChecks
    };
}

// --- 7. RETURN AUGMENTED ITEM ---
item.json = {
    docContent,
    compute
};

return item;

// Transform response data to legacy format with smart reference and date selection
const reference_priority_kws = ["אסמכתא", "אסמ", "חשבונית", "doc number", "invoice", "מסמך חיוב", "מסמך", "מס' תעודה", "מספר ת. יומן", "סימוכין", "מספר מסמך", "פקודה", "מספר מסמך התאמה"];
const date_priority_kws = ["תאריך אסמכתא", "ת.אסמ", "תאריך מסמך", "doc date", "תאריך חשבונית", "ת. למאזן", "תאריך למאזן", "ת. אירוע", "תאריך"];

function selectBestReference(references) {
  if (!references || references.length === 0) return { value: "", selectionMethod: "none_available" };
  if (references.length === 1) return { value: references[0]?.value || "", selectionMethod: "only_option" };
  for (const kw of reference_priority_kws) {
    const match = references.find(r => r.key && r.key.toLowerCase().includes(kw.toLowerCase()));
    if (match) return { value: match.value || "", selectionMethod: "keyword_match", matchedKeyword: kw };
  }
  return { value: references.find(r => r.value)?.value || "", selectionMethod: "fallback" };
}

function cleanReference(value) {
  if (!value) return "";
  let cleaned = String(value).trim().replace(/\s+/g, '').replace(/[^a-zA-Z0-9]/g, '');
  const match = cleaned.match(/^([a-zA-Z]*)(\d+)([a-zA-Z]*)$/);
  return match ? match[1] + match[2] : cleaned;
}

function selectBestDate(dates) {
  if (!dates || dates.length === 0) return { value: "" };
  for (const kw of date_priority_kws) {
    const match = dates.find(d => d.key && d.key.toLowerCase().includes(kw.toLowerCase()));
    if (match) return { value: match.value || "" };
  }
  return { value: dates[0]?.value || "" };
}

// פונקציית עזר להמרת תאריך ל-DD/MM/YYYY
const formatToDMY = (dateStr) => {
  if (!dateStr || !dateStr.includes('-')) return dateStr;
  const parts = dateStr.split('-');
  return parts.length === 3 ? `${parts[2]}/${parts[1]}/${parts[0]}` : dateStr;
};

return $input.all().map(({ json: { docContent: r, compute: c } }) => {
  const { doc_header: h, summary: s, transactions: t } = r;

  const lines = t.map(l => {
    const refSelection = selectBestReference(l.references || []);
    const dateSelection = selectBestDate(l.dates || []);
    return {
      id: cleanReference(refSelection.value),
      date: formatToDMY(dateSelection.value), // המרה כאן
      amount: Number(l.debit_amount) || -Number(l.credit_amount) || 0,
      balanceAmount: Number(l.accumulated_balance) || 0,
      notes: [l.transaction_description_he, l.note].filter(Boolean).join(" - "),
      refrences: l.references
    };
  });

  return { 
    docContent: r, 
    compute: c,
    response: {
      success: true,
      data: {
        documentDate: formatToDMY(h.date), // המרה כאן
        lines,
        summary: {
          totalsMatch: c.balance_reconciliation_result || c.debit_reconciliation_result,
          calculatedAmountSum: c.computed_total_debit,
          matchType: c.balance_reconciliation_result ? "exact" : "none",
          totalLines: t.length,
          documentTotal: s.final_accumulated_balance,
          calculatedBalanceSum: c.actual_final_balance,
          difference: c.balance_reconciliation_difference
        },
        clientName: r.doc_header.company_name_he
      },
      processedAt: new Date().toISOString()
    }
  };
});

