const getBBox = (vertices) => {
  const xs = vertices.map(v => v.x || 0);
  const ys = vertices.map(v => v.y || 0);
  const l = Math.min(...xs);
  const r = Math.max(...xs);
  const t = Math.min(...ys);
  const b = Math.max(...ys);
  return { l, r, t, b, w: r - l, h: b - t, cx: (l + r) / 2, cy: (t + b) / 2 };
};

/**
 * Detects if text is predominantly Right-to-Left (RTL)
 * Returns: { isRTL: boolean, rtlCount: number, ltrCount: number, hasText: boolean }
 */
const detectRTL = (text) => {
  if (!text || typeof text !== 'string') {
    return { isRTL: false, rtlCount: 0, ltrCount: 0, hasText: false };
  }

  // RTL Unicode ranges: Arabic, Hebrew, Syriac, Thaana, N'Ko
  const rtlChars = /[\u0590-\u05FF\u0600-\u06FF\u0700-\u074F\u0750-\u077F\u08A0-\u08FF\uFB50-\uFDFF\uFE70-\uFEFF]/g;

  // LTR letters (Latin, Cyrillic, Greek, etc.) - excluding numbers and punctuation
  const ltrChars = /[A-Za-z\u00C0-\u024F\u0400-\u04FF\u0370-\u03FF]/g;

  const rtlMatches = text.match(rtlChars);
  const ltrMatches = text.match(ltrChars);

  const rtlCount = rtlMatches ? rtlMatches.length : 0;
  const ltrCount = ltrMatches ? ltrMatches.length : 0;

  // If no letters found, not considered text
  const hasText = (rtlCount + ltrCount) > 0;

  // RTL if more than 50% of letters are RTL
  const isRTL = hasText && rtlCount > ltrCount;

  return { isRTL, rtlCount, ltrCount, hasText };
};


