for (const item of items) {
  const ocr = item.json?.json?.ocr_json || item.json?.ocr_json || item.json;
  const annotations = ocr.textAnnotations || ocr.responses?.[0]?.textAnnotations || [];

  for (let i = 1; i < annotations.length; i++) {
    const ann = annotations[i];
    const verts = ann.boundingPoly?.vertices;

    if (verts?.length === 4) {
      const bbox = getBBox(verts);

      if (bbox.w > 0 && bbox.h > 0) {
        const text = ann.description;
        if (detectRTL(text)) rtlCount++;

        words.push({
          t: text,
          x: Math.round(bbox.cx),
          y: Math.round(bbox.cy)
        });
      }
    }
